<script setup>
import { onMounted, reactive, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const tabs=[['summary','综合概览'],['orders','订单统计'],['traffic','流量排行'],['servers','节点排行'],['records','统计记录'],['user','用户明细'],['ranking','排行榜']]
const tab=ref('summary'),loading=ref(false),error=ref(''),summary=ref(null),rows=ref([]),range=reactive({start:'',end:''}),trafficType=ref('node'),rankingType=ref('user'),userId=ref(''),recordType=ref('d')
const startSec=()=>range.start?Math.floor(new Date(`${range.start}T00:00:00`).getTime()/1000):undefined
const endSec=()=>range.end?Math.floor(new Date(`${range.end}T23:59:59`).getTime()/1000):undefined
const currency=v=>`¥${(Number(v||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}`
const bytes=v=>{const n=Number(v||0);if(n>=1024**4)return `${(n/1024**4).toFixed(2)} TB`;if(n>=1024**3)return `${(n/1024**3).toFixed(2)} GB`;if(n>=1024**2)return `${(n/1024**2).toFixed(2)} MB`;return `${n.toLocaleString()} B`}
async function load(){loading.value=true;error.value='';try{if(tab.value==='summary')summary.value=await props.api('stat/getStats');else if(tab.value==='orders'){const q=new URLSearchParams();if(range.start)q.set('start_date',range.start);if(range.end)q.set('end_date',range.end);const data=await props.api(`stat/getOrder${q.size?`?${q}`:''}`);summary.value=data?.summary||null;rows.value=data?.list||[]}else if(tab.value==='traffic'||tab.value==='ranking'){const type=tab.value==='ranking'?rankingType.value:trafficType.value;const q=new URLSearchParams({type});if(startSec())q.set('start_time',String(startSec()));if(endSec())q.set('end_time',String(endSec()));const data=await props.api(`stat/getTrafficRank?${q}`);rows.value=data?.data||[]}else if(tab.value==='servers'){const path=range.end?'stat/getServerYesterdayRank':'stat/getServerLastRank';rows.value=await props.api(path)}else if(tab.value==='records'){const q=recordType.value?`?type=${encodeURIComponent(recordType.value)}`:'';rows.value=await props.api(`stat/getStatRecord${q}`)}else{if(!userId.value)throw new Error('请输入用户 ID。');const q=new URLSearchParams({user_id:userId.value,pageSize:'25'});rows.value=await props.api(`stat/getStatUser?${q}`)}}catch(e){error.value=e.message;rows.value=[]}finally{loading.value=false}}
function selectTab(id){tab.value=id;load()}
function columns(data){return data?.length?Object.keys(data[0]).slice(0,8):[]}
function formatValue(key,value){if(value===null||value===undefined)return '—';if(typeof value==='object')return JSON.stringify(value);if(/traffic|upload|download|total|value/i.test(key)&&typeof value==='number')return bytes(value);if(/amount|income|commission|price/i.test(key)&&typeof value==='number')return currency(value);return String(value)}
onMounted(load)
</script>
<template><section class="content-view stats-view"><div class="page-title-row"><div><p class="eyebrow">INFRASTRUCTURE / ANALYTICS</p><h1>统计报表<span class="title-period">.</span></h1><p class="page-subtitle">汇总统计、订单趋势与节点/用户流量排行</p></div><button class="refresh-button" @click="load">↻ <span>刷新报表</span></button></div><div class="gift-tabs"><button v-for="[id,name] in tabs" :key="id" :class="{selected:tab===id}" @click="selectTab(id)">{{name}}</button></div><p v-if="tab==='ranking'" class="table-hint">当前 Xboard 的 getRanking 路由缺少控制器实现；此排行榜使用有效的 getTrafficRank 接口读取用户或节点前十。</p><div class="stats-filters"><template v-if="['orders','traffic','servers'].includes(tab)"><label>开始日期<input v-model="range.start" type="date"/></label><label>结束日期<input v-model="range.end" type="date"/></label></template><label v-if="tab==='ranking'">排行榜对象<select v-model="rankingType"><option value="user">用户</option><option value="node">节点</option></select></label><label v-else-if="tab==='traffic'">流量排行对象<select v-model="trafficType"><option value="user">用户</option><option value="node">节点</option></select></label><label v-if="tab==='records'">记录类型<input v-model="recordType" placeholder="留空查全部"/></label><label v-if="tab==='user'">用户 ID<input v-model="userId" type="number" min="1" placeholder="输入用户 ID"/></label><button v-if="tab!=='summary'" class="refresh-button" @click="load">查询</button></div><div v-if="error" class="api-error"><span>!</span><div><b>统计查询失败</b><p>{{error}}</p></div><button @click="load">重试</button></div><div v-if="loading" class="table-state">正在读取报表…</div><template v-else-if="tab==='summary'&&summary"><div class="metric-grid stats-metrics"><article v-for="[key,label,value] in [['todayIncome','今日收入',summary.todayIncome],['currentMonthIncome','本月收入',summary.currentMonthIncome],['currentMonthNewUsers','本月新用户',summary.currentMonthNewUsers],['totalUsers','累计用户',summary.totalUsers],['activeUsers','有效订阅用户',summary.activeUsers],['onlineUsers','在线用户',summary.onlineUsers],['onlineDevices','在线设备',summary.onlineDevices],['onlineNodes','在线节点',summary.onlineNodes],['ticketPendingTotal','待处理工单',summary.ticketPendingTotal],['commissionPendingTotal','待发佣金',summary.commissionPendingTotal]]" :key="key" class="metric-card"><div class="metric-top">{{label}}</div><div class="metric-value">{{key.toLowerCase().includes('income')?currency(value):Number(value||0).toLocaleString()}}</div></article></div><div class="data-grid"><article v-for="[key,label] in [['todayTraffic','今日流量'],['monthTraffic','本月流量'],['totalTraffic','累计流量']]" :key="key" class="data-panel"><div class="panel-heading"><div><p class="eyebrow">TRAFFIC / {{key.toUpperCase()}}</p><h2>{{label}}</h2></div></div><div class="traffic-total">{{bytes(summary[key]?.total)}}<small>总计</small></div><div class="traffic-legend"><span>上行 {{bytes(summary[key]?.upload)}}</span><span>下行 {{bytes(summary[key]?.download)}}</span></div></article></div></template><template v-else-if="tab==='orders'&&summary"><div class="stats-summary-row"><article v-for="[key,label] in [['paid_total','收款总额'],['paid_count','收款笔数'],['commission_total','佣金总额'],['commission_count','佣金笔数'],['avg_paid_amount','平均订单'],['commission_rate','佣金占比']]" :key="key"><small>{{label}}</small><b>{{key.includes('total')||key.includes('amount')?currency(summary[key]):key==='commission_rate'?`${summary[key]}%`:summary[key]}}</b></article></div><DataTable :rows="rows" :columns="columns" :format-value="formatValue"/></template><DataTable v-else-if="Array.isArray(rows)" :rows="rows" :columns="columns" :format-value="formatValue"/><div v-if="tab==='servers'&&range.end" class="table-hint">设置结束日期将读取昨日节点排行；不填日期显示实时今日排行。</div><div class="footer-note"><span>XB CONTROL ROOM</span><span>报表来自 Xboard 统计 API <i>·</i> 时间范围使用面板时区</span></div></section></template>
<script>
const DataTable={props:{rows:Array,columns:Function,formatValue:Function},template:`<div class="users-table-wrap"><div v-if="!rows?.length" class="table-state">当前条件没有统计记录。</div><table v-else class="users-table report-table"><thead><tr><th v-for="col in columns(rows)" :key="col">{{col}}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id||index"><td v-for="col in columns(rows)" :key="col">{{formatValue(col,row[col])}}</td></tr></tbody></table></div>`}
export default {components:{DataTable}}
</script>
